    int n, a, b, ans = 0;
    scanf("%d%d%d", &n, &a, &b);

    vector<int> A(n);
    for (int i = 0; i < n; i++) scanf("%d", &A[i]);

    for (int i = 0; i < n; i++) {
        if (A[i] == 0 && A[n - i - 1] == 1) return printf("-1");
