#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, a, b;
    cin >> n >> a >> b;

    vector<int> A(n);
    for (int &x : A) cin >> x;

    long long ans = 0;

    for (int i = 0; i < n; ++i) {
        int j = n - i - 1;

        if ((A[i] == 0 && A[j] == 1) || (A[i] == 1 && A[j] == 0)) {
            cout << -1;
            return 0;
        }

        if (A[i] == 2 && A[j] == 2) {
            ans += min(a, b);
        } else if (A[i] == 2) {
            ans += (A[j] == 0 ? a : b);
        }
    }

    cout << ans;
    return 0;
}

